UPDATE orders
order_type = #{orderType}, table_id = #{tableId,jdbcType=BIGINT}, cashier_id = #{cashierId,jdbcType=BIGINT}, status = #{status}, total_amount = #{totalAmount}, note = #{note,jdbcType=VARCHAR}, customer_name = #{customerName,jdbcType=VARCHAR}, customer_phone = #{customerPhone,jdbcType=VARCHAR}, pickup_date = #{pickupDate,jdbcType=DATE}, pickup_code = #{pickupCode,jdbcType=INTEGER}, pickup_time = #{pickupTime,jdbcType=TIMESTAMP}, version = version + 1,
